/** Dialog layout: preview on the left, scrolling form on the right (same pattern as the building dialog). */
export declare const TREE_DIALOG_CSS = "\n#tree_generator_dialog .dialog_content {display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,360px);gap:24px;max-height:calc(100vh - 190px);overflow:auto;}\n#tree_generator_dialog .tree_view {min-width:0;position:sticky;top:0;align-self:start;}\n#tree_generator_dialog .tree_view canvas {width:100%;height:min(440px,calc(100vh - 320px));min-height:200px;display:block;border-radius:8px;touch-action:none;cursor:grab;}\n#tree_generator_dialog .tree_heading {display:flex;justify-content:space-between;gap:8px;font-size:12px;line-height:16px;letter-spacing:.4px;color:var(--color-subtle_text);margin:0 0 8px;}\n#tree_generator_dialog .tree_stats {font-size:12px;padding-top:12px;}\n#tree_generator_dialog .tree_hint {font-size:12px;line-height:16px;color:var(--color-subtle_text);padding-top:8px;}\n#tree_generator_dialog .tree_error {color:#f2ac78;}\n#tree_generator_dialog .form {display:block;}\n@media(max-width:800px){#tree_generator_dialog .dialog_content{grid-template-columns:1fr;}#tree_generator_dialog .tree_view{position:static;}#tree_generator_dialog .tree_view canvas{height:clamp(128px,24vh,200px);min-height:128px;}}\n";
